// Iterate every merged item (one raw Apollo response per branch that fired).
const inputItems = items;

let orgs = [];
let totalRawCount = 0;
const branchErrors = [];
const availableKeys = new Set();

for (const it of inputItems) {
  const raw = it.json || {};
  Object.keys(raw).forEach(k => availableKeys.add(k));
  if (raw.error) {
    branchErrors.push(`${raw._source_branch || 'unknown'}: ${typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error).slice(0, 300)}`);
  }
  const branchOrgs = [
    ...(Array.isArray(raw.accounts)      ? raw.accounts      : []),
    ...(Array.isArray(raw.organizations) ? raw.organizations : []),
    ...(Array.isArray(raw.companies)     ? raw.companies     : []),
    ...(Array.isArray(raw.results)       ? raw.results       : [])
  ];
  totalRawCount += branchOrgs.length;
  for (const org of branchOrgs) {
    org.__native_match  = raw._native_match  || false;
    org.__source_branch = raw._source_branch || '';
  }
  orgs.push(...branchOrgs);
  console.log(`[APOLLO] branch=${raw._source_branch || 'unknown'} native_match=${raw._native_match || false} orgs_in_branch=${branchOrgs.length}`);
}

if (orgs.length === 0) {
  console.warn('[APOLLO] No organizations found across any branch.');
  return [{
    json: {
      error: branchErrors.length
        ? `Apollo request failed: ${branchErrors.join(' | ')}`
        : 'Apollo returned no organizations',
      branches_received: inputItems.length,
      raw_response: JSON.stringify(inputItems[0]?.json || {}).slice(0, 1500),
      available_keys: [...availableKeys].join(', ')
    }
  }];
}

console.log(`[APOLLO] Received ${totalRawCount} raw organization(s) across ${inputItems.length} branch(es).`);

const seen = new Set();
const noDomainOrgs = [];

const unique = orgs.filter(org => {
  const domain = (
    org.website_url ||
    org.primary_domain ||
    org.domain ||
    ''
  ).toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/$/, '')
    .split('/')[0];

  if (!domain) {
    noDomainOrgs.push(org.name || org.organization_id || 'unknown');
    return true; // keep it; Normalize & Filter Websites1 decides what to do with it
  }
  if (seen.has(domain)) return false;
  seen.add(domain);
  return true;
});

if (noDomainOrgs.length > 0) {
  console.warn(`[APOLLO] ${noDomainOrgs.length} of ${orgs.length} orgs have NO website_url/primary_domain/domain from Apollo:`, JSON.stringify(noDomainOrgs));
}

console.log(`[APOLLO] After cross-branch dedup: ${unique.length} of ${orgs.length} orgs remain.`);

const mapped = unique.map(org => {
  const website =
    org.website_url ||
    org.primary_domain ||
    org.domain ||
    '';

  const rawDomain = website
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/$/, '')
    .split('/')[0];

  const phone =
    org.sanitized_phone ||
    org.phone ||
    org.primary_phone?.sanitized_number ||
    org.primary_phone?.number ||
    '';

  const linkedin = org.linkedin_url || org.social_links?.linkedin || '';
  const twitter  = org.twitter_url  || org.social_links?.twitter  || '';
  const facebook = org.facebook_url || org.social_links?.facebook || '';

  const technologies = Array.isArray(org.technology_names)
    ? org.technology_names.join(', ')
    : (org.technology_names || '');

  const keywords = Array.isArray(org.keywords)
    ? org.keywords.join(', ')
    : (org.keywords || '');

  return {
    json: {
      company:            org.name             || '',
      website,
      primary_domain:     rawDomain,
      apollo_org_id:      org.organization_id  || org.id || '',
      linkedin, phone, twitter, facebook,
      logo_url:           org.logo_url         || '',
      city:               org.city             || org.organization_city    || '',
      state:              org.state            || org.organization_state   || '',
      country:            org.country          || org.organization_country || '',
      employee_count:     org.estimated_num_employees || org.employee_count || 0,
      founded_year:       org.founded_year     || '',
      industry:           org.industry         || org.primary_industry || '',
      apollo_description: org.short_description || org.seo_description || org.description || '',
      annual_revenue:     org.annual_revenue_printed || org.annual_revenue || org.organization_revenue_printed || '',
      total_funding:      org.total_funding    || '',
      funding_stage:      org.latest_funding_stage || '',
      funding_date:       org.latest_funding_round_date || '',
      technologies,
      keywords,
      apollo_native_match:   org.__native_match  || false,
      matched_native_signal: org.__source_branch || ''
    }
  };
});

console.log(`[APOLLO] Passing ${mapped.length} deduplicated companies downstream (${mapped.filter(m => !m.json.website).length} with no website).`);

return mapped;

