const before = items.length;

const withWebsite = [];
const noWebsiteButHasLinkedIn = [];
const droppedEntirely = [];

for (const i of items) {
  const site = i.json.website && String(i.json.website).trim();

  if (site) {
    let url = site;
    if (!url.startsWith('http')) url = `https://${url}`;
    url = url.replace(/\/$/, '');
    withWebsite.push({ json: { ...i.json, website: url } });
    continue;
  }

  if (i.json.linkedin) {
    // Kept and flagged. The Has Website? branch routes these past the website
    // fetch so they are still scored and enriched via Apollo data.
    noWebsiteButHasLinkedIn.push({
      json: { ...i.json, website: '', no_website_reason: 'no_website_has_linkedin' }
    });
    continue;
  }

  droppedEntirely.push(i.json.company || 'unknown');
}

if (noWebsiteButHasLinkedIn.length > 0) {
  console.warn(`[NO WEBSITE] ${noWebsiteButHasLinkedIn.length} of ${before} companies have no website but do have LinkedIn: flagged, not dropped:`,
    JSON.stringify(noWebsiteButHasLinkedIn.map(i => i.json.company)));
}
if (droppedEntirely.length > 0) {
  console.warn(`[DROPPED] ${droppedEntirely.length} of ${before} companies dropped entirely (no website AND no LinkedIn):`, JSON.stringify(droppedEntirely));
}

console.log(`[NORMALIZE] in=${before} | with_website=${withWebsite.length} | no_website_has_linkedin=${noWebsiteButHasLinkedIn.length} | dropped=${droppedEntirely.length}`);

return [...withWebsite, ...noWebsiteButHasLinkedIn];

