// Extract structured signals (meta/OG/schema.org/H1-H2/careers/pricing/tech
// fingerprints) from the raw HTML, then run the healthcare + buying-signal
// keyword scans on CLEANED TEXT so script/nav markup can't cause false hits.
const companyData = $('Loop Over Items1').item.json;
const inputData = $('Prepare Input1').first().json;
const html = $json.data || '';

function firstMatch(re) {
  const m = html.match(re);
  return m ? m[1].trim() : '';
}

const title = firstMatch(/<title[^>]*>([\s\S]*?)<\/title>/i);
const metaDescription = firstMatch(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i);
const ogTitle = firstMatch(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']*)["']/i);
const ogDescription = firstMatch(/<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i);

const h1s = [...html.matchAll(/<h1[^>]*>([\s\S]*?)<\/h1>/gi)].map(m => m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 5);
const h2s = [...html.matchAll(/<h2[^>]*>([\s\S]*?)<\/h2>/gi)].map(m => m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 8);

// schema.org JSON-LD blocks
let schemaOrg = [];
try {
  const ldBlocks = [...html.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
  for (const b of ldBlocks) {
    try { schemaOrg.push(JSON.parse(b[1].trim())); } catch (e) { /* skip malformed block */ }
  }
} catch (e) { /* no-op */ }

// Nav-link based page presence checks
const hasCareers = /href=["'][^"']*(careers|jobs|join-us|join-our-team)[^"']*["']/i.test(html) || /we['’]?re hiring/i.test(html);
const hasPricing = /href=["'][^"']*pricing[^"']*["']/i.test(html);
const hasBlog    = /href=["'][^"']*(blog|resources|insights)[^"']*["']/i.test(html);

// Embedded tool fingerprints (buying-signal for AI/automation/CRM readiness)
const techFingerprints = {
  intercom:   /widget\.intercom\.io|Intercom\(/i.test(html),
  drift:      /js\.driftt\.com/i.test(html),
  hubspot:    /js\.hs-scripts\.com|hubspot/i.test(html),
  salesforce: /salesforce|force\.com/i.test(html),
  calendly:   /calendly\.com/i.test(html),
  zendesk:    /zendesk/i.test(html),
  livechat:   /livechatinc\.com/i.test(html)
};

const copyrightYear = firstMatch(/©\s*(\d{4})/) || firstMatch(/copyright\s*(\d{4})/i);

// ---- Cleaned text used for ALL keyword scans ----
const stripToText = s => s
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const lowerText = stripToText(html).toLowerCase();

// Keyword matcher with word boundaries (so "cro" doesn't match "across",
// "series a" doesn't match "series and", etc.)
const escapeRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const kwRegex = k => new RegExp(
  (/^\w/.test(k) ? '(?<![a-z0-9])' : '') + escapeRe(k) + (/\w$/.test(k) ? '(?![a-z0-9])' : '')
);
const scan = categories => {
  const out = {};
  for (const [cat, kws] of Object.entries(categories)) {
    const hits = kws.filter(k => kwRegex(k).test(lowerText));
    out[cat] = { present: hits.length > 0, hit_count: hits.length, matched_keywords: hits };
  }
  return out;
};

// ---- Healthcare vertical buying-signal keyword scan ----
const HEALTHCARE_CATEGORIES = {
  patient_acquisition:             ['patient acquisition', 'new patient', 'patient leads', 'grow your practice', 'patient marketing', 'patient referral', 'patient growth'],
  patient_engagement:              ['patient engagement', 'patient portal', 'appointment reminder', 'patient communication', 'two-way texting', 'patient satisfaction', 'patient experience'],
  practice_management:             ['practice management', 'pm system', 'scheduling software', 'medical billing software', 'front desk', 'practice management software'],
  telehealth:                      ['telehealth', 'telemedicine', 'virtual visit', 'video consultation', 'remote care', 'virtual care'],
  intelligent_provider_management: ['provider management', 'credentialing', 'provider scheduling', 'staff scheduling', 'provider network', 'locum tenens', 'provider onboarding'],
  ehr:                             ['ehr', 'electronic health record', 'e-prescribing', 'ehr integration'],
  revenue_cycle_management:        ['revenue cycle management', 'rcm', 'medical billing', 'claims processing', 'denial management', 'coding compliance', 'medical coding'],
  clinical_trials:                 ['clinical trial', 'clinical research', 'trial recruitment', 'irb', 'protocol amendment', 'contract research organization', 'cro'],
  emr_integrations:                ['emr integration', 'electronic medical record', 'hl7', 'fhir', 'interoperability', 'api integration']
};
const healthcare_signals = scan(HEALTHCARE_CATEGORIES);
const healthcare_fit_score = Math.min(10, Object.values(healthcare_signals).filter(s => s.present).length * 2);

// ---- 11 Buying-Intent Signals (keyword-based, no AI) ----
// Generic phrases that fire on almost every marketing site ("introducing",
// "case study", "partners with", "powered by", "now available") were removed.
const BUYING_SIGNAL_CATEGORIES = {
  recent_funding:        ['raised $', 'series a', 'series b', 'series c', 'series d', 'funding round', 'secured funding', 'seed round', 'venture capital', 'investment round'],
  promoted_executives:   ['promoted to', 'newly appointed', 'appoints new', 'welcomes new ceo', 'welcomes new cto', 'new chief', 'takes over as'],
  new_client_signed:     ['new client', 'signed with', 'proud to announce', 'welcome our new client', 'client win', 'now serving'],
  partnerships:          ['strategic partnership', 'in partnership with', 'announces partnership', 'joint venture', 'collaboration with', 'integration partner'],
  office_expansion:      ['new office', 'expanding to', 'opens office', 'expansion into', 'relocated to', 'new headquarters', 'growing footprint'],
  merger_or_acquisition: ['acquires', 'acquired by', 'merger', 'merged with', 'acquisition of', 'has acquired', 'to acquire'],
  hiring_growth:         ['we are hiring', "we're hiring", 'we’re hiring', 'join our team', 'open positions', 'now hiring', 'career opportunities', 'growing team'],
  leadership_changes:    ['joins as', 'steps down', 'new leadership', 'leadership transition', 'appointed as ceo', 'appointed as cto'],
  product_launches:      ['launches new', 'new product', 'announcing the launch', 'unveils', 'proud to launch'],
  technology_adoption:   ['now using', 'migrated to', 'implementation of', 'digital transformation'],
  revenue_growth:        ['revenue growth', 'record revenue', 'year-over-year growth', 'increased revenue', 'grew revenue', 'strongest quarter', 'record year']
};
const buying_signals = scan(BUYING_SIGNAL_CATEGORIES);

const signal_count = Object.values(buying_signals).filter(s => s.present).length;
const signal_summary = Object.entries(buying_signals)
  .filter(([_, v]) => v.present)
  .map(([k]) => k.replace(/_/g, ' '))
  .join(', ') || 'None detected';

// ---- Filter against user-selected signals ----
// Native-capable signals (recent_funding, hiring_growth) were already filtered by
// Apollo's own query parameters upstream; a company reaches here via a native
// branch only if companyData.apollo_native_match is true. Every other selected
// signal is matched by the text scan above.
const selectedSignals = Array.isArray(inputData.Selected_Signals) ? inputData.Selected_Signals : [];
const NATIVE_SIGNALS = ['recent_funding', 'hiring_growth'];
const selectedNative = selectedSignals.filter(s => NATIVE_SIGNALS.includes(s));
const selectedText = selectedSignals.filter(s => !NATIVE_SIGNALS.includes(s));

let matchedSignals = [];
let signal_match;

if (selectedSignals.length === 0) {
  signal_match = true;
  matchedSignals = ['(no filter applied)'];
} else {
  const nativePass = selectedNative.length > 0 && companyData.apollo_native_match === true;
  const textMatches = selectedText.filter(sig => buying_signals[sig] && buying_signals[sig].present);
  matchedSignals = [
    ...(nativePass ? [companyData.matched_native_signal || 'apollo_native'] : []),
    ...textMatches
  ];
  signal_match = nativePass || textMatches.length > 0;
}

console.log(`[SIGNAL FILTER] company=${companyData.company} | selected=${JSON.stringify(selectedSignals)} | matched=${JSON.stringify(matchedSignals)} | pass=${signal_match}`);

// ---- Flatten main content to plain text for the LLM ----
const mainMatch    = html.match(/<main[\s\S]*?<\/main>/i);
const articleMatch = html.match(/<article[\s\S]*?<\/article>/i);
const bodyMatch    = html.match(/<body[\s\S]*?<\/body>/i);

const rawSection = (mainMatch && mainMatch[0])
  || (articleMatch && articleMatch[0])
  || (bodyMatch && bodyMatch[0])
  || html;

const text = rawSection
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<header[\s\S]*?<\/header>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    ...companyData,
    website_content: text.substring(0, 8000),
    page_title: title,
    meta_description: metaDescription || ogDescription,
    og_title: ogTitle,
    h1_headings: h1s,
    h2_headings: h2s,
    schema_org: schemaOrg,
    has_careers_page: hasCareers,
    has_pricing_page: hasPricing,
    has_blog: hasBlog,
    tech_fingerprints: techFingerprints,
    copyright_year: copyrightYear,
    healthcare_signals,
    healthcare_fit_score,
    buying_signals,
    signal_count,
    signal_summary,
    selected_signals: selectedSignals,
    matched_signals: matchedSignals,
    signal_match,
    Job_Title: inputData.Job_Title
  }
}];

// LinkedIn-only company: nothing to scrape, so only Apollo-native signal
// matches (funding / hiring) can qualify when signals are selected.
const company = $input.first().json;
const input = $('Prepare Input1').first().json;

const selected = Array.isArray(input.Selected_Signals) ? input.Selected_Signals : [];
const NATIVE = ['recent_funding', 'hiring_growth'];
const selectedNative = selected.filter(s => NATIVE.includes(s));

let signal_match;
let matched;
if (selected.length === 0) {
  signal_match = true;
  matched = ['(no filter applied)'];
} else {
  signal_match = selectedNative.length > 0 && company.apollo_native_match === true;
  matched = signal_match ? [company.matched_native_signal || 'apollo_native'] : [];
}

console.log(`[NO WEBSITE] ${company.company} | selected=${JSON.stringify(selected)} | pass=${signal_match}`);

return [{
  json: {
    ...company,
    website_content: '',
    page_title: '',
    meta_description: '',
    og_title: '',
    h1_headings: [],
    h2_headings: [],
    schema_org: [],
    has_careers_page: false,
    has_pricing_page: false,
    has_blog: false,
    tech_fingerprints: {},
    copyright_year: '',
    healthcare_signals: {},
    healthcare_fit_score: 0,
    buying_signals: {},
    signal_count: 0,
    signal_summary: 'None detected',
    selected_signals: selected,
    matched_signals: matched,
    signal_match,
    Job_Title: input.Job_Title
  }
}];

const companyData = $('Loop Over Items1').item.json;
console.log(`[SKIP] No matching buying signal: ${companyData.company} (${companyData.website}) | wanted=${JSON.stringify($json.selected_signals)}`);
return [{
  json: {
    ...companyData,
    website_content: '',
    dm_name: '', dm_title: '', dm_email: '', dm_linkedin: '', dm_phone: '',
    all_contacts: '[]', contacts_found: 0,
    business_summary: 'Skipped: no matching buying signal',
    target_customer: '', key_pain_points: '', automation_opportunities: '',
    dm_personalized_email: '',
    industry: companyData.industry || '',
    ai_readiness: 0, automation_need: 0, growth_signal: 0,
