const src = $('Prep For Enrichment1').first().json;

let enriched = {};
try {
  const rawJson = $input.first().json || {};
  enriched =
    rawJson.person ||
    (Array.isArray(rawJson.matches) ? rawJson.matches[0] : null) ||
    {};
} catch(e) {}

const emailStatus = enriched.email_status || '';
const creditIssue = ['credits_exhausted', 'unavailable'].includes(emailStatus);

if (creditIssue) {
  console.warn(`[CREDIT WARN] company=${src.company} email_status=${emailStatus}`);
}

console.log(`[ENRICH] company=${src.company} | enriched_email=${enriched.email || 'none'} | email_status=${emailStatus} | fallback_email=${src._top_email || 'none'}`);

let allPeopleRaw = [];
try { allPeopleRaw = JSON.parse(src._raw_people || '[]'); } catch(e) {}

const dm_name     = `${enriched.first_name || src._top_first_name || ''} ${enriched.last_name || src._top_last_name || ''}`.trim();
const dm_title    = enriched.title        || src._top_title    || '';
const dm_linkedin = enriched.linkedin_url || src._top_linkedin || '';

const dm_email =
  (enriched.email && !['unavailable','credits_exhausted'].includes(emailStatus)
    ? enriched.email : null) ||
  src._top_email ||
  '';

const dm_phone =
  (enriched.phone_numbers?.length > 0
    ? (enriched.phone_numbers.find(p => p.type === 'work')?.sanitized_number ||
       enriched.phone_numbers[0]?.sanitized_number)
    : null) ||
  enriched.sanitized_phone ||
  src._top_phone ||
  src.phone ||
  '';

const contacts = allPeopleRaw.map(p => ({
  name:     `${p.first_name || ''} ${p.last_name || ''}`.trim(),
  title:    p.title           || '',
  email:    p.email           || '',
  linkedin: p.linkedin_url    || '',
  phone:    p.sanitized_phone || p.phone || ''
}));

// Capture person_id BEFORE destructuring strips it away
const dm_person_id = src._top_person_id || enriched.id || '';

const {
  _raw_people, _top_person_id, _top_first_name,
  _top_last_name, _top_title, _top_linkedin,
  _top_email, _top_phone, _has_person,
  _top_organization_id, _top_last_name_obfuscated,
  _has_email, _has_direct_phone, _has_city,
  _has_state, _has_country, _top_person_raw,
  ...cleanCompany
} = src;

return [{
  json: {
    ...cleanCompany,
    dm_name,
    dm_title,
    dm_email,
    dm_linkedin,
    dm_phone,
    dm_person_id,
    all_contacts:   JSON.stringify(contacts),
    contacts_found: contacts.length
  }
}];

