const src = $('Merge People & Company1').item.json;

let parsed = {};
let parseFailed = false;
try {
  let raw = $json.output || '{}';
  raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) raw = match[0];
  raw = raw.replace(/,\s*([}\]])/g, '$1');
  parsed = JSON.parse(raw);
} catch (e) {
  parseFailed = true;
  console.warn(`[PARSE FAIL] company=${src.company} error=${e.message}`);
  parsed = {
    industry: src.industry || '',
    business_summary: 'Could not parse AI response',
    target_customer: '', automation_opportunities: '',
    key_pain_points: '', personalized_message: '',
    ai_readiness: 3, automation_need: 5, growth_signal: 3
  };
}

return [{
  json: {
    company:                  src.company            || '',
    website:                  src.website            || '',
    linkedin:                 src.linkedin           || '',
    phone:                    src.phone              || '',
    twitter:                  src.twitter            || '',
    facebook:                 src.facebook           || '',
    logo_url:                 src.logo_url           || '',
    city:                     src.city               || '',
    state:                    src.state              || '',
    country:                  src.country            || '',
    employee_count:           src.employee_count     || 0,
    founded_year:             src.founded_year       || '',
    annual_revenue:           src.annual_revenue     || '',
    total_funding:            src.total_funding      || '',
    funding_stage:            src.funding_stage      || '',
    funding_date:             src.funding_date       || '',
    technologies:             src.technologies       || '',
    keywords:                 src.keywords           || '',
    apollo_description:       src.apollo_description || '',
    dm_name:                  src.dm_name            || '',
    dm_title:                 src.dm_title           || '',
    dm_email:                 src.dm_email           || '',
    dm_linkedin:              src.dm_linkedin        || '',
    dm_phone:                 src.dm_phone           || '',
    dm_person_id:             src.dm_person_id       || '',
    all_contacts:             src.all_contacts       || '[]',
    contacts_found:           src.contacts_found     || 0,
    industry:                 parsed.industry                 || src.industry || '',
    business_summary:         parsed.business_summary         || '',
    target_customer:          parsed.target_customer          || '',
    automation_opportunities: parsed.automation_opportunities || '',
    key_pain_points:          parsed.key_pain_points          || '',
    dm_personalized_email:    parsed.personalized_message     || '',
    ai_readiness:             Number(parsed.ai_readiness   || 3),
    automation_need:          Number(parsed.automation_need || 5),
    growth_signal:            Number(parsed.growth_signal   || 3),
    signal_count:             src.signal_count        || 0,
    signal_summary:           src.signal_summary       || 'None detected',
    healthcare_fit_score:     src.healthcare_fit_score || 0,
    parse_failed:             parseFailed,
    content_length:           (src.website_content || '').length
  }
}];

const lead = $input.first().json;

const weights = {
  company_fit: 0.18, technology: 0.18, intent_growth: 0.17,
  website_quality: 0.17, contact_completeness: 0.18, funding: 0.12,
  email_bonus: 8, phone_bonus: 5, revenue_bonus: 3
};

const clamp10 = v => Math.min(10, Math.max(0, Number(v || 0)));

const ai     = clamp10(lead.ai_readiness);
const auto   = clamp10(lead.automation_need);
const growth = clamp10(lead.growth_signal);
const size   = Number(lead.employee_count || 0);

let sizeScore;
if      (size > 500) sizeScore = 10;
else if (size > 100) sizeScore = 7;
else if (size > 20)  sizeScore = 5;
else if (size > 5)   sizeScore = 3;
else                 sizeScore = 1;

const contentLen = Number(lead.content_length || 0);
const contentQuality = contentLen > 2000 ? 1.0 : contentLen > 500 ? 0.85 : 0.7;

const techScore = String(lead.technologies || '').length > 0 ? 10 : 3;

// Intent = LLM growth signal blended with how many buying signals were detected
const signalScore = Math.min(10, Number(lead.signal_count || 0) * 2);
const intentScore = growth * 0.6 + signalScore * 0.4;

let fundingScore = 0;
if (lead.funding_stage) fundingScore += 6;
if (lead.total_funding) fundingScore += 4;
fundingScore = Math.min(10, fundingScore);

let contactScore = 0;
if (lead.dm_email) contactScore += 5;
if (lead.dm_phone) contactScore += 3;
if (lead.dm_title) contactScore += 2;
contactScore = Math.min(10, contactScore);

const weightedScore =
  (sizeScore           * weights.company_fit) +
  (techScore           * weights.technology) +
  (intentScore         * weights.intent_growth) +
  ((auto * 0.5 + ai * 0.5) * weights.website_quality) +
  (contactScore        * weights.contact_completeness) +
  (fundingScore        * weights.funding);

const emailBonus   = lead.dm_email       ? weights.email_bonus   : 0;
const phoneBonus   = lead.dm_phone       ? weights.phone_bonus   : 0;
const revenueBonus = lead.annual_revenue ? weights.revenue_bonus : 0;

// Healthcare fit only counts when the run targeted Healthcare Technology
const isHealthcareRun = /healthcare/i.test(String($('Prepare Input1').first().json.Market_Segments || ''));
const healthcareBonus = isHealthcareRun ? Math.round(clamp10(lead.healthcare_fit_score) * 0.5) : 0;

const raw_score  = Math.round(weightedScore * 10 * contentQuality);
const lead_score = Math.min(100, raw_score + emailBonus + phoneBonus + revenueBonus + healthcareBonus);

return [{ json: { ...lead, lead_score, healthcare_bonus: healthcareBonus } }];

// Drop skipped / scoreless leads, then rank by score (highest first).
const leads = $input.all()
  .map(i => i.json)
  .filter(j => j && !j.skip && Number(j.lead_score) > 0 && j.company);

leads.sort((a, b) => Number(b.lead_score) - Number(a.lead_score));

console.log(`[RANK] in=${$input.all().length} | qualified=${leads.length}`);

return leads.map(j => ({ json: j }));

// Keep only leads that are NEW (not already in the sheet, not duplicated within
// this run), then cap at Max_lead. Leads are already sorted by score.
const normKey = (website, company) => {
  const w = String(website || '').toLowerCase().trim()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .split(/[\/?#]/)[0];
  return w || ('co:' + String(company || '').toLowerCase().trim());
};

const maxLead = Number($('Prepare Input1').first().json.Max_lead) || 10;

const existing = new Set();
for (const row of $input.all()) {
  const j = row.json || {};
  if (!j.Website && !j.Company) continue;   // empty item from an empty sheet
  existing.add(normKey(j.Website, j.Company));
}

const leads = $('Filter & Rank Leads').all().map(i => i.json);

const seen = new Set();
const fresh = [];
let dupes = 0;
for (const lead of leads) {
  const k = normKey(lead.website, lead.company);
  if (existing.has(k) || seen.has(k)) { dupes++; continue; }
  seen.add(k);
  fresh.push(lead);
}

const limited = fresh.slice(0, maxLead);
console.log(`[DEDUPE] ranked=${leads.length} | already_in_sheet_or_dupe=${dupes} | new=${fresh.length} | kept=${limited.length} (Max_lead=${maxLead})`);

return limited.map(j => ({ json: j }));

const leads = $input.all().map(i => i.json);
const form = $('Prepare Input1').first().json;

const lines = [];
lines.push(`AI Automation Lead Finder: ${leads.length} new lead(s)`);
lines.push(`Search: ${form.business_type} | ${form.location}, ${form.country}`);
lines.push('='.repeat(60));
lines.push('');

leads.forEach((l, idx) => {
  lines.push(`#${idx + 1}  ${l.company}  |  Score ${l.lead_score}/100`);
  lines.push(`   Website:         ${l.website || 'n/a (LinkedIn only)'}`);
  lines.push(`   Decision maker:  ${l.dm_name || 'not found'}${l.dm_title ? ' (' + l.dm_title + ')' : ''}`);
  lines.push(`   Email:           ${l.dm_email || 'n/a'}`);
  lines.push(`   Phone:           ${l.dm_phone || 'n/a'}`);
  lines.push(`   LinkedIn:        ${l.dm_linkedin || l.linkedin || 'n/a'}`);
  lines.push(`   Buying signals:  ${l.signal_summary || 'None detected'}`);
  lines.push(`   Summary:         ${l.business_summary || ''}`);
  lines.push('');
});

return [{ json: { report: lines.join('\n'), count: leads.length } }];

// Apollo posts { people: [{ id, status, phone_numbers: [...] }] } after a phone reveal.
const body = $input.first().json.body || {};
const people = Array.isArray(body.people) ? body.people : [];

const out = [];
for (const p of people) {
  const nums = Array.isArray(p.phone_numbers) ? p.phone_numbers : [];
  const best = nums.find(n => n.type === 'work') || nums[0];
  const phone = best?.sanitized_number || best?.raw_number || '';
  if (p.id && phone) out.push({ json: { person_id: p.id, phone } });
}

console.log(`[PHONE CALLBACK] people=${people.length} | with_phone=${out.length}`);
return out;
